// Normalise, then screen. Two thirds of what hits a public form is not a lead, and
// everything that gets past this node costs a model call and a salesperson's attention.
const FREE = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com', 'proton.me', 'protonmail.com', 'aol.com', 'live.com', 'msn.com'];
const DISPOSABLE = ['mailinator.com', 'guerrillamail.com', '10minutemail.com', 'tempmail.com', 'trashmail.com', 'yopmail.com', 'sharklasers.com'];

return $input.all().map((item) => {
  const b = item.json.body || item.json;
  const email = String(b.email || '').toLowerCase().trim();
  const domain = email.split('@')[1] || '';
  const message = String(b.message || b.notes || b.comments || '').trim();

  const reasons = [];

  // Honeypot: a hidden field a human never fills in and most bots always do.
  if (String(b.website_url || b.hp || '').trim()) reasons.push('honeypot filled');
  if (!email.includes('@')) reasons.push('no valid email');
  if (DISPOSABLE.indexOf(domain) !== -1) reasons.push('disposable domain');
  if (message.length > 2000) reasons.push('message absurdly long');
  if (message.split('http').length - 1 > 3) reasons.push('link stuffing');

  const submittedAt = b.submitted_at || new Date().toISOString();

  return { json: {
    lead_id: b.lead_id || (domain + '-' + (b.first_name || email.split('@')[0] || '')).toLowerCase(),
    first_name: b.first_name || b.firstName || String(b.name || '').split(' ')[0] || '',
    last_name: b.last_name || b.lastName || String(b.name || '').split(' ').slice(1).join(' ') || '',
    email: email,
    domain: FREE.indexOf(domain) === -1 ? domain : '',
    personal_email: FREE.indexOf(domain) !== -1,
    company: b.company || b.company_name || '',
    phone: b.phone || '',
    message: message,
    source: b.source || b.utm_source || 'website',
    campaign: b.utm_campaign || '',
    form: b.form_name || 'contact',
    submitted_at: submittedAt,
    is_spam: reasons.length > 0,
    spam_reasons: reasons
  }};
});

// Merge the triage back, and compute speed-to-lead. That number is the whole reason
// inbound automation exists - responses inside five minutes convert several times
// better than responses an hour later, and it is the metric to put in front of a client.
const leads = $('looks like a person?').all();
const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const lead = Object.assign({}, leads[i].json);
  const res = $input.all()[i].json || {};
  const text = String(((((res.choices || [])[0]) || {}).message || {}).content || '').trim();

  let t = { segment: 'warm', score: 50, buying_signal: '', what_they_want: '', urgency: 'unknown', suggested_first_line: '', needs_human_now: true };
  if (text) {
    const body = text.startsWith('```') ? text.replace(/^```[a-z]*\n?/, '').replace(/```$/, '').trim() : text;
    try { t = JSON.parse(body); } catch (e) { /* an unparseable triage routes to a human */ }
  }

  const submitted = Date.parse(lead.submitted_at) || Date.now();
  const seconds = Math.max(0, Math.round((Date.now() - submitted) / 1000));

  out.push({ json: Object.assign({}, lead, t, {
    speed_to_lead_seconds: seconds,
    hot: t.segment === 'hot' || t.needs_human_now === true,
    stage: 'replied',
    triaged_at: new Date().toISOString()
  })});
}

return out;

// Everything that is not hot still gets a home and a next step. 'not_a_fit',
// 'vendor_pitch' and 'support' are routed away rather than left in the sales pile.
const ROUTE = {
  warm: 'nurture sequence',
  nurture: 'nurture sequence',
  not_a_fit: 'archive - polite decline',
  vendor_pitch: 'archive - selling to us',
  support: 'forward to support'
};

return $input.all().map((item) => ({ json: Object.assign({}, item.json, {
  routed_to: ROUTE[item.json.segment] || 'nurture sequence',
  stage: ['not_a_fit', 'vendor_pitch', 'support'].indexOf(item.json.segment) !== -1 ? 'suppressed' : 'enriched'
})}));

// Log what was screened out, so a client who says 'we got a form and you never told
// me' has an answer waiting. Spam is dropped, not hidden.
return $input.all().map((item) => ({ json: {
  submitted_at: item.json.submitted_at,
  email: item.json.email,
  reasons: (item.json.spam_reasons || []).join(', '),
  message: String(item.json.message || '').slice(0, 200)
}}));
